 * string is never written inline in a composable.
 */
object Strings {

    const val RATES_TITLE = "Rates"
    const val RATES_SEARCH_HINT = "Search by code or name"
    const val RATES_NOTHING_FOUND = "Nothing found"
    const val ERROR_TITLE = "Could not load the rates"
    const val RETRY = "Retry"
    const val REFRESH = "Refresh"
    const val RATE_HISTORY_TITLE = "Last 30 days"
    const val NO_DATA = "No data for the period"
    const val NOT_ENOUGH_DATA = "Not enough data to calculate the change"
    const val BACK = "Back"

    fun ratesSubtitle(base: String, date: String): String = "1 $base · $date"

    fun rateDetailsTitle(code: String, base: String): String = "$code / $base"

    fun currentRate(base: String, rate: String, code: String): String = "1 $base = $rate $code"

    fun changePeriod(start: String, end: String): String = "Change $start – $end"

}
package com.fxrates.feature.rates.details

import androidx.compose.runtime.Immutable
import com.fxrates.core.utils.Empty
import com.fxrates.feature.rates.details.model.HistoryItem
import com.fxrates.feature.rates.model.Trend

@Immutable
internal data class RateDetailsUiState(
    val title: String = String.Empty,
    val content: Content = Content.Loading,
) {

    @Immutable
    sealed class Content {

        data object Loading : Content()

        data object Error : Content()

        data object NoData : Content()

        /**
         * @property rate the latest rate, e.g. `1 USD = 0.8900 EUR`.
         * @property date the date of the latest rate.
         * @property history the rate of every day of the period, newest first.
         */
        data class Data(
            val rate: String,
            val date: String,
            val change: Change,
            val history: List<HistoryItem>,
        ) : Content()

    }

    @Immutable
    sealed class Change {

        data object NotEnoughData : Change()

        data class Value(
            val period: String,
            val absolute: String,
            val percent: String,
            val trend: Trend,
        ) : Change()

    }

}
